mapper.select:
SELECT 
FROM node_system
WHERE node_system_ip_address = #{ipAddress}
AND node_system_port = #{port}

mapper.update:
UPDATE node_system SET
    node_system_error_count = COALESCE(node_system_error_count, 0) + 1,
    node_system_last_error_time = #{errorTime},
    node_system_last_error_message = #{errorMessage},
    update_time = #{errorTime}
WHERE node_system_id = #{nodeId}

mapper.select:
SELECT FROM node_system WHERE 1=1
AND (node_system_name LIKE CONCAT('%', #{keyword}, '%') OR node_system_application_name LIKE CONCAT('%', #{keyword}, '%') OR node_system_ip_address LIKE CONCAT('%', #{keyword}, '%'))
AND node_system_status = #{status}
AND node_system_application_name = #{applicationName}
ORDER BY node_system_last_heartbeat_time DESC
